package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class Revision28Tests {
 MainActivity a;
 @Before public void setup(){org.robolectric.RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void end(){a.onDestroy();}
 @Test public void twoConfirmationsAndCancellationPreserveOriginal(){MainActivity.Item old=a.items.get(0);String original=old.text;int count=a.items.size();a.saveItem(null,"  "+old.title.toUpperCase(Locale.ROOT)+"  ","Neuer Inhalt","prompt",new ArrayList<>(),()->{});AlertDialog first=ShadowAlertDialog.getLatestAlertDialog();assertEquals(count,a.items.size());first.getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog second=ShadowAlertDialog.getLatestAlertDialog();assertNotSame(first,second);assertEquals(original,old.text);second.getButton(-2).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(original,old.text);assertEquals(count,a.items.size());a.saveItem(null,old.title,"Neuer Inhalt","prompt",new ArrayList<>(),()->{});ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(count,a.items.size());assertEquals("Neuer Inhalt",old.text);assertEquals("prompt",old.type);}
 @Test public void searchIncludesBothTypesCompletedAndDatesAndSurvivesReload()throws Exception{a.items.clear();MainActivity.Item prompt=new MainActivity.Item("Recherche","Gemeinsames Suchwort","prompt");MainActivity.Item block=new MainActivity.Item("Baustein","Gemeinsames Suchwort","block");block.archived=true;block.createdAt=block.updatedAt=1735689600000L;a.items.add(prompt);a.items.add(block);a.persist();a.tab="prompt";a.archivedView=false;a.search.setText("Suchwort");assertEquals(1,a.rows.getChildCount());a.showOverview();a.overviewSearch.setText("Suchwort");assertEquals(2,a.overviewRows.getChildCount());assertTrue(text(a.overviewRows).contains("Erledigt · Baustein"));a.overviewSearch.setText("Suchwort 01.01.2025");assertEquals(1,a.overviewRows.getChildCount());assertTrue(text(a.overviewRows).contains("Baustein"));assertTrue(a.matches(block,"2025-01-01"));assertFalse(a.matches(block,"Suchwort fehlt"));assertEquals(block.updatedAt,a.parse(block.json()).updatedAt);assertEquals(0,a.parse(new org.json.JSONObject("{\"title\":\"Alt\",\"text\":\"Text\",\"type\":\"prompt\"}")).updatedAt);}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void compactEditorContainsAttachmentAndKeepsHeaderHeight()throws Exception{a.showDraft();assertSame(a.editor.getParent(),a.attachButton.getParent());View content=a.findViewById(android.R.id.content);content.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(800,1073741824));content.layout(0,0,360,800);assertEquals(a.dp(36),a.root.getChildAt(0).getHeight());android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(360,800,android.graphics.Bitmap.Config.ARGB_8888);content.draw(new android.graphics.Canvas(b));try(java.io.OutputStream out=new java.io.FileOutputStream("tests/Promptwerk-2.8-Editor.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}a.editor.setText("Bleibt erhalten");a.expandEditor();a.expandedDialog.dismiss();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertSame(a.editorBox,a.editor.getParent());assertEquals("Bleibt erhalten",a.editor.getText().toString());}
 @Test public void importConflictsAreAtomicAndDoNotCreateDuplicateNames(){MainActivity.Item old=a.items.get(0);String text=old.text;int size=a.items.size();ArrayList<MainActivity.Item> incoming=new ArrayList<>();incoming.add(new MainActivity.Item(old.title.toUpperCase(Locale.ROOT),"Ersatz","prompt"));incoming.add(new MainActivity.Item("Importiert","Neu","block"));a.mergeImport(incoming,()->{});ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-2).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(size,a.items.size());assertEquals(text,a.items.get(0).text);a.mergeImport(incoming,()->{});ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(size+1,a.items.size());assertEquals("Ersatz",a.sameName(old.title,null).text);}
 String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=" "+text(((ViewGroup)v).getChildAt(i));return s;}
}
